export function getShareMessages(path: string): PlatformMessages & { pageUrl: string } {
  const pageUrl = url(path);
  const factory = PAGE_MESSAGES[path];
  if (factory) return { ...factory(pageUrl), pageUrl };
  const slug = path.startsWith("/") ? path.slice(1) : path;
  if (SLUG_TO_ANALYSIS[slug]) return { ...FORENSIC_ANALYSIS_MESSAGES(slug, pageUrl), pageUrl };
  return { ...DEFAULT_MESSAGES(path), pageUrl };
}
